// The workers schema.

/** A Worker's own fields, as a create gives them. A worker process, which beats while it runs. A worker that misses its deadline is missing, and the leases its principal holds on jobs are released, so its jobs go back in the queue. */
export type WorkerFields = {
  /** The principal the worker runs as. */
  subject: string;
};

/** A Worker as a read returns it: its own fields, then its behaviors'. */
export type Worker = WorkerFields & {
  /** Workflow: The state the instance is in. */
  readonly status: WorkerState;
  /** Presence: The heartbeat: deadline, when the instance is missed unless beaten, lastBeatAt, both in epoch milliseconds or null, missed, and released, the instances whose lease the last miss expired, by schema (null before a miss). */
  readonly presence?: JSONObject;
};

/** A merge patch of a Worker's own fields (RFC 7386): null removes an optional field. Its behaviors' fields change through their operations. */
export type WorkerPatch = {
  /** The principal the worker runs as. */
  subject?: string;
};

/** A state of a Worker's Workflow. */
export type WorkerState = 'active' | 'missing';

/** The parameters of Workflow's transition: Moves the instance to another state along a transition the config lists. A transition that names a permission needs a caller who holds it. */
export type WorkerTransitionParams = {
  /** The state to move to. */
  to: WorkerState;
};

/** What Workflow's transition returns. */
export type WorkerTransitionResult = {
  /** The state the instance was in. */
  from: WorkerState;
  /** The state it is in now. */
  to: WorkerState;
};

/** The parameters of Presence's beat: Moves the deadline to ttlMs from now and clears missed, and onBeat moves the status when it is one of its from states. Only the principal whose subject the instance's principalField holds. */
export type WorkerBeatParams = Record<string, never>;

/** What Presence's beat returns. */
export type WorkerBeatResult = {
  /** When the instance is missed unless beaten again, in epoch milliseconds. */
  deadline: number;
};

/** The parameters of Presence's miss: Applies the miss of an instance past its deadline and not missed yet: sets missed, moves the status with onMissed when it is one of its from states, and expires the principal's leases on the releaseLeases schemas that were not renewed after its last beat, recording which in released. Any principal who may write the instance may call it; on any other instance it changes nothing. The engine's runner calls it every sweepMs. */
export type WorkerMissParams = Record<string, never>;

/** What Presence's miss returns. */
export type WorkerMissResult = {
  /** Whether this call missed the instance. */
  missed: boolean;
  /** When it did: the instances whose lease it expired, by releaseLeases schema; empty when another instance that stands for the principal is present. */
  released?: { [key: string]: string[] };
};

/** Each operation a Worker's behaviors add: its scope, parameters and result. */
export type WorkerOperations = {
  transition: { scope: 'instance'; params: WorkerTransitionParams; result: WorkerTransitionResult };
  beat: { scope: 'instance'; params: WorkerBeatParams; result: WorkerBeatResult };
  miss: { scope: 'instance'; params: WorkerMissParams; result: WorkerMissResult };
};

/** The name of an operation on one Worker. */
export type WorkerInstanceOperation = 'transition' | 'beat' | 'miss';

/** The codes the vetoes of a Worker's behaviors carry, by behavior: what a refused call's details.code holds. */
export type WorkerVetoes = {
  Workflow: 'already_in_state' | 'terminal_state' | 'transition_not_allowed' | 'no_status';
  Presence: 'no_principal' | 'not_principal' | 'principal_fixed';
};

/** A Worker create's options: its id, and each behavior's create parameters. */
export type WorkerCreateOptions = Omit<CreateOptions, 'behaviors'>;

/** A Worker write's options: the sequence it expects, and each behavior's preconditions. */
export type WorkerWriteOptions = Omit<WriteOptions, 'preconditions'>;

/** isWorkerVeto is isVeto with the behaviors of a Worker and their codes. */
export function isWorkerVeto<B extends keyof WorkerVetoes>(error: unknown, behavior?: B, codes?: WorkerVetoes[B] | ReadonlyArray<WorkerVetoes[B]>): error is EngineVeto {
  return isVeto(error, behavior, codes);
}

/** The workers schema's calls, typed: the engine's built-in operations, then each operation its behaviors add. */
export interface WorkersClient {
  /** create stores a new Worker, with its behaviors' create parameters. */
  create(data: WorkerFields, options?: WorkerCreateOptions): Promise<Instance<Worker>>;
  /** get reads a Worker; one that does not exist is 404 not_found. */
  get(id: string, options?: CallOptions): Promise<Instance<Worker>>;
  /** list returns a page in creation order. */
  list(options?: ListOptions): Promise<InstancePage<Worker>>;
  /** update applies a merge patch of the own fields. */
  update(id: string, patch: WorkerPatch, options?: WorkerWriteOptions): Promise<Instance<Worker>>;
  /** delete removes a Worker. */
  delete(id: string, options?: WorkerWriteOptions): Promise<void>;
  /** operate calls an instance operation and returns its result with the instance's sequence after it. */
  operate<K extends WorkerInstanceOperation>(id: string, operation: K, params: WorkerOperations[K]['params'], options?: WorkerWriteOptions): Promise<OperationOutcome<WorkerOperations[K]['result']>>;
  /** Workflow's transition: Moves the instance to another state along a transition the config lists. A transition that names a permission needs a caller who holds it. */
  transition(id: string, params: WorkerTransitionParams, options?: WorkerWriteOptions): Promise<WorkerTransitionResult>;
  /** Presence's beat: Moves the deadline to ttlMs from now and clears missed, and onBeat moves the status when it is one of its from states. Only the principal whose subject the instance's principalField holds. */
  beat(id: string, params?: WorkerBeatParams, options?: WorkerWriteOptions): Promise<WorkerBeatResult>;
  /** Presence's miss: Applies the miss of an instance past its deadline and not missed yet: sets missed, moves the status with onMissed when it is one of its from states, and expires the principal's leases on the releaseLeases schemas that were not renewed after its last beat, recording which in released. Any principal who may write the instance may call it; on any other instance it changes nothing. The engine's runner calls it every sweepMs. */
  miss(id: string, params?: WorkerMissParams, options?: WorkerWriteOptions): Promise<WorkerMissResult>;
}

/** workersClient wraps an EngineClient with the workers schema's types. */
export function workersClient(client: EngineClient): WorkersClient {
  return {
    create(data, options) {
      return client.instances.create<Worker>('workers', data, options);
    },
    get(id, options) {
      return client.instances.get<Worker>('workers', id, options);
    },
    list(options) {
      return client.instances.list<Worker>('workers', options);
    },
    update(id, patch, options) {
      return client.instances.update<Worker>('workers', id, patch, options);
    },
    delete(id, options) {
      return client.instances.delete('workers', id, options);
    },
    operate<K extends WorkerInstanceOperation>(id: string, operation: K, params: WorkerOperations[K]['params'], options?: WorkerWriteOptions) {
      return client.instances.operate<WorkerOperations[K]['result']>('workers', id, operation, params, options);
    },
    transition(id, params, options) {
      return client.instances.invoke<WorkerTransitionResult>('workers', id, 'transition', params, options);
    },
    beat(id, params, options) {
      return client.instances.invoke<WorkerBeatResult>('workers', id, 'beat', params ?? {}, options);
    },
    miss(id, params, options) {
      return client.instances.invoke<WorkerMissResult>('workers', id, 'miss', params ?? {}, options);
    },
  };
}
